import {initialState,validState,metrics,currentAssets,alarms,clock,advance,acknowledge,createOrder,startOrder,finishOrder,createTask,finishTask,receiveStock,saveSettings,event,reportRows,toCSV} from './model.js';
const STORAGE='rpc-suite-premium-demo-v1';
let state;try{const saved=JSON.parse(localStorage.getItem(STORAGE));state=validState(saved)?saved:initialState();}catch{state=initialState();}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=0)=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(v);
const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);
const iconPaths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',assets:'M4 20V8l5 3V5l5 4V3h6v17z M8 16h1 M13 16h1 M18 16h1',process:'M5 4v7 M5 15v5 M12 4v3 M12 11v9 M19 4v10 M19 18v2 M2 11h6 M9 7h6 M16 14h6',orders:'M7 3h10v4H7z M5 5H3v16h18V5h-2 M7 12h10 M7 16h7',maintenance:'M14 5a5 5 0 0 0-6 6l-5 5 4 4 5-5a5 5 0 0 0 7-6l-4 2-3-3z',energy:'M13 2 4 14h7l-1 8 10-13h-7z',stock:'m3 7 9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10',analytics:'M4 20V4 M4 20h17 M8 16l4-6 4 3 5-8',reports:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h8',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M18 7a3 3 0 0 1 0 6 M22 21v-2a4 4 0 0 0-3-4',history:'M3 12a9 9 0 1 0 3-7 M3 3v6h6 M12 7v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'M15 15l6 6 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4 10-10',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',play:'m8 4 13 8-13 8z'};
const icon=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[id]||iconPaths.overview}"/></svg>`;
const modules=[['visao-geral','Visão geral','overview','Operação'],['equipamentos','Equipamentos','assets','Operação'],['supervisao','Supervisão do processo','process','Operação'],['ordens','Ordens de produção','orders','Operação'],['manutencao','Manutenção','maintenance','Operação'],['energia','Energia','energy','Inteligência'],['estoque','Estoque e materiais','stock','Inteligência'],['analises','Análises e OEE','analytics','Inteligência'],['relatorios','Relatórios','reports','Inteligência'],['usuarios','Perfis de acesso','users','Administração'],['historico','Histórico de eventos','history','Administração'],['configuracoes','Configurações','settings','Administração']];
const subtitles={ 'visao-geral':'Produção, equipamentos e decisões no mesmo lugar.',equipamentos:'Estados, variáveis e o contexto de cada equipamento.',supervisao:'Do preparo ao envase: entenda o processo visualmente.',ordens:'Planejamento e execução conectados ao chão de fábrica.',manutencao:'Da ocorrência à verificação da entrega.',energia:'Demanda, consumo e custo em uma visão organizada.',estoque:'Materiais disponíveis para a continuidade da operação.',analises:'Entenda o indicador e os pontos de perda.',relatorios:'Transforme os registros em informação compartilhável.',usuarios:'Um exemplo de acesso adequado a cada responsabilidade.',historico:'A rastreabilidade das ações realizadas nesta demonstração.',configuracoes:'Explore parâmetros e veja como eles afetam o exemplo.'};
let route='visao-geral',queries={},filters={},chartPeriod='turno',toastTimer,lastTrigger,tourStep=0;
let group='';$('#module-nav').innerHTML=modules.map(([id,title,ico,g])=>{const heading=g!==group?`<p class="nav-group">${g}</p>`:'';group=g;return heading+`<a href="#/${id}" data-route="${id}">${icon(ico)}<span>${title}</span>${id==='manutencao'?'<span class="nav-count" id="maintenance-count"></span>':''}</a>`;}).join('');
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{toast('O armazenamento do navegador não está disponível. O exemplo continua nesta sessão.');}}
function toast(message,error=false){clearTimeout(toastTimer);const t=$('#toast');const host=document.querySelector('dialog[open]')||document.body;if(t.parentElement!==host)host.append(t);t.textContent=message;t.classList.toggle('error',error);t.hidden=false;toastTimer=setTimeout(()=>{t.hidden=true;},5500);}
function mutate(action,message){try{const result=action();persist();render();if(message)toast(message);return result;}catch(error){toast(error.message,true);return false;}}
const statusNames={running:'Em operação',attention:'Atenção',maintenance:'Em manutenção',standby:'Disponível',done:'Concluída',planned:'Planejada',open:'Aberta'};
const badge=(status,label)=>`<span class="badge ${status}"><i></i>${esc(label||statusNames[status]||status)}</span>`;
const actionButton=(label,action,id='',kind='secondary')=>`<button class="button ${kind}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
function heading(title,desc,actions=''){return `<div class="page-heading"><div><p class="page-kicker">${esc(state.settings.plant)} <span>• Cenário ${clock(state)}</span></p><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
const metric=(label,value,note='',kind='',extra='')=>`<article class="metric ${kind}"><div class="metric-label">${label}${extra}</div><strong>${value}</strong><p>${note}</p></article>`;
const panelHead=(title,subtitle='',actions='')=>`<div class="panel-heading"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions}</div>`;
function chart(values,labels,unit='',key='production',color='#6a8137'){
 const max=Math.max(...values)*1.18||1,w=780,h=220,left=58,right=18,top=16,bottom=32;const x=i=>left+i*(w-left-right)/(values.length-1||1),y=v=>h-bottom-(h-top-bottom)*v/max;
 const points=values.map((v,i)=>[x(i),y(v)]),path=points.map((p,i)=>(i?'L':'M')+p.map(v=>v.toFixed(1)).join(' ')).join(' ');const area=path+` L ${x(values.length-1)} ${h-bottom} L ${left} ${h-bottom} Z`;
 return `<div class="chart-wrap"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Gráfico: ${esc(labels.map((l,i)=>l+': '+num(values[i])+unit).join('; '))}"><defs><linearGradient id="fill-${key}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".2"/><stop offset="100%" stop-color="${color}" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(f=>`<line x1="${left}" x2="${w-right}" y1="${y(max*f)}" y2="${y(max*f)}" stroke="#e9ebe9" stroke-dasharray="3 5"/><text x="${left-10}" y="${y(max*f)+4}" text-anchor="end">${num(max*f)}</text>`).join('')}<path d="${area}" fill="url(#fill-${key})"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${points.map(([a,b],i)=>`<circle cx="${a}" cy="${b}" r="${i===points.length-1?5:3}" fill="${color}" stroke="white" stroke-width="2"><title>${esc(labels[i])}: ${num(values[i])} ${esc(unit)}</title></circle>`).join('')}${labels.map((l,i)=>`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${esc(l)}</text>`).join('')}</svg></div><details class="chart-data"><summary>Ver dados do gráfico</summary><div class="table-scroll"><table><thead><tr><th>Período</th><th>Valor (${esc(unit||'unidades')})</th></tr></thead><tbody>${labels.map((l,i)=>`<tr><td>${esc(l)}</td><td>${num(values[i])}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function productionSeries(){const m=metrics(state);if(chartPeriod==='semana')return {values:[4520,4790,4380,5120,4980,4670,m.produced],labels:['Seg','Ter','Qua','Qui','Sex','Sáb','Hoje']};return {values:[0,.09,.2,.33,.46,.58,.71,.84,1].map(f=>Math.round(m.produced*f)),labels:['08h','09h','10h','11h','12h','13h','14h','15h',clock(state)]};}
const assetName=id=>currentAssets(state).find(a=>a.id===id)?.name||id;
function alarmList(compact=false){const list=alarms(state);if(!list.length)return `<div class="empty-state">${icon('check')}<h3>Sem alertas de processo</h3><p>O cenário atual está dentro dos limites de exemplo.</p></div>`;return `<div class="alarm-list">${list.map(a=>`<article class="alarm-item"><span class="alarm-icon ${a.severity}">${icon('alert')}</span><div><h3>${esc(a.title)}</h3><p>${esc(assetName(a.asset))} · ${esc(a.detail)}</p><div class="alarm-actions"><button data-action="asset" data-id="${a.asset}">Investigar ${icon('arrow')}</button>${a.acknowledged?'<span class="ack-label">Ciência registrada</span>':`<button data-action="ack" data-id="${a.id}">Registrar ciência</button>`}</div></div></article>`).join('')}</div>`;}
function assetTable(items=currentAssets(state)){return `<div class="table-scroll"><table><thead><tr><th>Equipamento</th><th>Área</th><th>Estado atual</th><th>Variável</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><button class="entity-link" data-action="asset" data-id="${a.id}"><span class="asset-symbol">${icon(a.id.startsWith('TK')?'stock':'assets')}</span><span><strong>${esc(a.name)}</strong><small>${a.id}</small></span></button></td><td>${esc(a.area)}</td><td>${badge(a.status)}</td><td><strong class="tabular">${num(a.value)} <small>${a.unit}</small></strong><small class="cell-caption">${a.variable}</small></td><td><button class="row-arrow" data-action="asset" data-id="${a.id}" aria-label="Detalhes de ${esc(a.name)}">↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">Nenhum equipamento encontrado para este filtro.</td></tr>'}</tbody></table></div>`;}
function orderList(){return `<div class="order-list">${state.orders.slice(-3).map(o=>`<button class="order-summary" data-action="order" data-id="${o.id}"><div><span>${o.id}</span>${badge(o.status,o.status==='running'?'Em produção':undefined)}</div><h3>${esc(o.product)}</h3><div class="progress"><span style="width:${o.done/o.qty*100}%"></span></div><p>${num(o.done)} / ${num(o.qty)} unidades <span>${num(o.done/o.qty*100)}%</span></p></button>`).join('')}</div>`;}
function overview(){const m=metrics(state),a=alarms(state),series=productionSeries();return heading('Visão geral da operação',subtitles[route],`<select class="select" id="scenario" aria-label="Cenário de processo"><option value="attention" ${state.scenario==='attention'?'selected':''}>Com pontos de atenção</option><option value="normal" ${state.scenario==='normal'?'selected':''}>Operação estável</option></select>${actionButton(icon('play')+' Avançar cenário','advance','','primary')}`)+`<div class="metrics-grid">${metric('Eficiência global · OEE',num(m.oee,1)+'<small>%</small>','Disponibilidade × performance × qualidade','metric-feature',`<div class="mini-ring" style="--value:${m.oee}%" aria-hidden="true"></div>`)}${metric('Produção no turno',num(m.produced),`de ${num(m.target)} unidades planejadas`,'',`<span class="metric-icon">${icon('orders')}</span>`)}${metric('Disponibilidade',num(m.availability,1)+'<small>%</small>','451,2 min disponíveis / 480 min de referência','',`<span class="metric-icon">${icon('assets')}</span>`)}${metric('Qualidade',num(m.quality,1)+'<small>%</small>','Índice ilustrativo de peças conformes','',`<span class="metric-icon">${icon('check')}</span>`)}</div><div class="overview-top"><section class="panel production-panel">${panelHead('Ritmo de produção',chartPeriod==='turno'?'Produção acumulada no turno de exemplo':'Produção diária · últimos 7 dias de exemplo',`<div class="segmented" role="group" aria-label="Período do gráfico"><button data-action="period" data-id="turno" aria-pressed="${chartPeriod==='turno'}">Turno</button><button data-action="period" data-id="semana" aria-pressed="${chartPeriod==='semana'}">Semana</button></div>`)}<div class="chart-total"><strong>${num(chartPeriod==='turno'?m.produced:series.values.reduce((x,y)=>x+y,0))}</strong><span>unidades no período</span><div class="chart-legend"><i></i>Produção registrada</div></div>${chart(series.values,series.labels,'un','overview')}</section><section class="panel attention-panel">${panelHead('Sua atenção agora',`${a.length} ${a.length===1?'condição de processo':'condições de processo'}`,`<span class="count-pill">${a.filter(x=>!x.acknowledged).length} sem ciência</span>`)}${alarmList(true)}<div class="attention-footer">${state.stock.filter(x=>x.qty<x.min).length} materiais abaixo do mínimo <a href="#/estoque">Consultar estoque ↗</a></div></section></div><div class="overview-bottom"><section class="panel">${panelHead('Equipamentos da unidade','Estados atuais do cenário',`<a class="subtle-link" href="#/equipamentos">Ver todos ↗</a>`)}${assetTable()}</section><section class="panel">${panelHead('Ordens de produção',`${state.orders.filter(o=>o.status==='running').length} em andamento`,`<a class="subtle-link" href="#/ordens">Abrir módulo ↗</a>`)}${orderList()}</section></div><div class="context-note">${icon('process')}<p><strong>Uma informação leva à próxima.</strong> Clique em um equipamento para investigar a condição e consultar a manutenção relacionada.</p></div>`;}
const searchField=(placeholder)=>`<label class="table-search">${icon('search')}<input type="search" id="table-query" data-query value="${esc(queries[route]||'')}" placeholder="${placeholder}" aria-label="${placeholder}"></label>`;
function equipment(){let items=currentAssets(state).filter(a=>(a.name+' '+a.id+' '+a.area).toLowerCase().includes((queries[route]||'').toLowerCase()));if(filters[route]&&filters[route]!=='all')items=items.filter(a=>a.status===filters[route]);return heading('Equipamentos e monitoramento',subtitles[route],actionButton('Avançar cenário','advance','','primary'))+`<div class="asset-state-strip">${[['running','Em operação'],['attention','Com atenção'],['maintenance','Em manutenção'],['standby','Em reserva']].map(([key,label])=>`<div>${badge(key,label)}<strong>${currentAssets(state).filter(a=>a.status===key).length}</strong></div>`).join('')}</div><section class="panel">${panelHead('Ativos conectados','Selecione um equipamento para abrir as variáveis e os registros.')}<div class="table-toolbar">${searchField('Buscar equipamento ou área')}<select data-filter class="select" aria-label="Filtrar estado"><option value="all">Todos os estados</option>${['running','attention','maintenance','standby'].map(s=>`<option value="${s}" ${filters[route]===s?'selected':''}>${statusNames[s]}</option>`).join('')}</select></div>${assetTable(items)}</section>`;}
function processView(){const tank=currentAssets(state).find(a=>a.id==='TK-01'),mixer=currentAssets(state).find(a=>a.id==='MX-01'),filler=currentAssets(state).find(a=>a.id==='FL-01');return heading('Supervisão do processo',subtitles[route],actionButton(icon('play')+' Avançar cenário','advance','','primary'))+`<section class="panel scada-panel">${panelHead('Linha de preparo e envase','Sinótico demonstrativo · selecione um equipamento',`<span class="badge running"><i></i>Processo de exemplo</span>`)}<div class="process-diagram"><svg viewBox="0 0 1000 390" role="img" aria-label="Fluxo ilustrativo do tanque de preparo ao misturador, envasadora e embalagem"><defs><pattern id="tank-hatch" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8 8 0" stroke="#e0e2e0"/></pattern></defs><path d="M190 220H365 M495 220H730 M850 220h100" fill="none" stroke="#e3e5e3" stroke-width="15"/><path d="M190 220H365 M495 220H730 M850 220h100" fill="none" stroke="#7b7d7b" stroke-width="5" stroke-dasharray="12 5"/><path d="M130 75V45h300v30" fill="none" stroke="#c5c7c5" stroke-width="6"/><rect x="80" y="95" width="115" height="180" rx="22" fill="#f6f8f6" stroke="#a1a3a1" stroke-width="3"/><clipPath id="tank-clip"><rect x="82" y="97" width="111" height="176" rx="20"/></clipPath><rect x="82" y="${273-176*tank.value/100}" width="111" height="${176*tank.value/100}" fill="#d2d4d2" clip-path="url(#tank-clip)"/><ellipse cx="137" cy="95" rx="57" ry="15" fill="#eff1ef" stroke="#a1a3a1" stroke-width="3"/><rect x="365" y="85" width="135" height="205" rx="30" fill="#eef0ee" stroke="#a1a3a1" stroke-width="3"/><rect x="368" y="170" width="129" height="90" fill="#d9dbd9" rx="18"/><ellipse cx="432" cy="85" rx="67" ry="17" fill="#eff1ef" stroke="#a1a3a1" stroke-width="3"/><path d="M432 85v145 M402 177l60 30 M402 210l60-30" stroke="#757775" stroke-width="4" fill="none"/><rect x="410" y="48" width="44" height="32" fill="#a4a6a4" rx="7"/><circle cx="280" cy="220" r="29" fill="#fff" stroke="#848684" stroke-width="3"/><path d="m268 205 24 15-24 15z" fill="#848684"/><rect x="685" y="140" width="195" height="125" rx="12" fill="#e8eae8" stroke="#a1a3a1" stroke-width="3"/><rect x="750" y="95" width="80" height="45" rx="5" fill="#b8bab8"/><path d="M762 140v35 M800 140v35" stroke="#858785" stroke-width="4"/><rect x="713" y="265" width="225" height="16" fill="#aeb0ae" rx="7"/>${[720,760,800,840,880].map(x=>`<rect x="${x}" y="207" width="22" height="55" rx="5" fill="#d2d4d2" stroke="#909290"/><rect x="${x+5}" y="195" width="12" height="13" rx="3" fill="#a5a7a5"/>`).join('')}<text x="137" y="330" text-anchor="middle">Tanque de preparo</text><text x="432" y="330" text-anchor="middle">Mistura e temperatura</text><text x="790" y="330" text-anchor="middle">Envase e embalagem</text></svg><button class="process-point tank" data-action="asset" data-id="TK-01"><span>TK-01</span><strong>${tank.value}%</strong>${badge(tank.status,tank.status==='attention'?'Nível reduzido':'Nível normal')}</button><button class="process-point mixer" data-action="asset" data-id="MX-01"><span>MX-01</span><strong>${mixer.value} °C</strong>${badge(mixer.status,mixer.status==='attention'?'Verificar temperatura':'Temperatura normal')}</button><button class="process-point filler" data-action="asset" data-id="FL-01"><span>FL-01</span><strong>${num(filler.value)} un/h</strong>${badge(filler.status)}</button></div><p class="diagram-caption">Representação conceitual. Os pontos abrem informações de exemplo; não existem comandos para equipamentos reais.</p></section><div class="two-columns"><section class="panel">${panelHead('Condições do processo','O reconhecimento registra ciência, sem eliminar a condição.')}${alarmList()}</section><section class="panel">${panelHead('Conexões da operação','Uma arquitetura ajustada à aplicação.')}<div class="architecture-list"><div><span>Campo</span><p>Sensores de nível, temperatura e sinais dos equipamentos.</p></div><div><span>Controle</span><p>CLP, intertravamentos e comunicação industrial.</p></div><div><span>Supervisão</span><p>Estados, alarmes, tendências e registros.</p></div><div><span>Gestão</span><p>Ordens, manutenção, indicadores e relatórios.</p></div></div></section></div>`;}
function ordersView(){const list=state.orders.filter(o=>(o.id+' '+o.product).toLowerCase().includes((queries[route]||'').toLowerCase())&&(!filters[route]||filters[route]==='all'||o.status===filters[route]));const m=metrics(state);return heading('Ordens de produção',subtitles[route],actionButton(icon('plus')+' Nova ordem de exemplo','new-order','','primary'))+`<div class="metrics-grid three">${metric('Planejado no turno',num(m.target)+'<small> un</small>','Soma das quantidades das ordens')}${metric('Produzido no exemplo',num(m.produced)+'<small> un</small>','Atualizado ao avançar ou concluir ordens')}${metric('Atendimento do plano',num(m.progress,1)+'<small>%</small>',`${state.orders.filter(o=>o.status==='done').length} ${state.orders.filter(o=>o.status==='done').length===1?'ordem concluída':'ordens concluídas'}`)}</div><section class="panel">${panelHead('Plano e execução','As ações abaixo afetam somente o exemplo neste navegador.')}<div class="table-toolbar">${searchField('Buscar ordem ou produto')}<select class="select" data-filter aria-label="Estado da ordem"><option value="all">Todos os estados</option>${['planned','running','done'].map(s=>`<option value="${s}" ${filters[route]===s?'selected':''}>${s==='running'?'Em produção':statusNames[s]}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Ordem / produto</th><th>Equipamento</th><th>Progresso</th><th>Estado</th><th>Ação de exemplo</th></tr></thead><tbody>${list.map(o=>`<tr><td><button class="entity-link" data-action="order" data-id="${o.id}"><span><strong>${o.id}</strong><small>${esc(o.product)}</small></span></button></td><td>Envasadora 01</td><td><div class="table-progress"><span>${num(o.done)} / ${num(o.qty)}</span><div class="progress"><span style="width:${o.done/o.qty*100}%"></span></div></div></td><td>${badge(o.status,o.status==='running'?'Em produção':undefined)}</td><td>${o.status==='planned'?actionButton('Iniciar exemplo','start-order',o.id):o.status==='running'?actionButton('Concluir exemplo','finish-order',o.id):'<span class="muted">Entrega registrada</span>'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">Nenhuma ordem para este filtro.</td></tr>'}</tbody></table></div></section>`;}
function maintenanceView(){const list=state.tasks.filter(t=>(t.id+' '+t.title+' '+assetName(t.asset)).toLowerCase().includes((queries[route]||'').toLowerCase())&&(!filters[route]||filters[route]==='all'||t.status===filters[route]));return heading('Manutenção e intervenções',subtitles[route],actionButton(icon('plus')+' Nova solicitação','new-task','','primary'))+`<div class="metrics-grid three">${metric('Solicitações abertas',state.tasks.filter(t=>['open','planned'].includes(t.status)).length,'Pendências e intervenções programadas')}${metric('Em execução',state.tasks.filter(t=>t.status==='running').length,'Atividades em andamento no exemplo')}${metric('Concluídas',state.tasks.filter(t=>t.status==='done').length,'Com os três itens do checklist verificados')}</div><section class="panel">${panelHead('Quadro de manutenção','Abra uma solicitação e experimente o checklist.')}<div class="table-toolbar">${searchField('Buscar solicitação ou equipamento')}<select data-filter class="select" aria-label="Filtrar manutenção"><option value="all">Todos os estados</option>${['open','planned','running','done'].map(s=>`<option value="${s}" ${filters[route]===s?'selected':''}>${s==='running'?'Em execução':statusNames[s]}</option>`).join('')}</select></div><div class="maintenance-grid">${list.map(t=>`<button class="maintenance-card" data-action="task" data-id="${t.id}"><div><span>${t.id}</span>${badge(t.status,t.status==='running'?'Em execução':undefined)}</div><h3>${esc(t.title)}</h3><p>${esc(assetName(t.asset))}</p><footer><span class="priority ${t.priority==='Alta'?'high':''}">${t.priority==='Alta'?'● ':''}${t.priority}</span><span>${t.checks.filter(Boolean).length}/3 verificados ↗</span></footer></button>`).join('')||'<p class="empty-row">Nenhuma solicitação para este filtro.</p>'}</div></section>`;}
function energyView(){const kwh=2460+state.tick*38,demand=Math.min(280,182+state.tick*2),series=[112,128,164,188,176,194,demand];return heading('Energia e demanda',subtitles[route],actionButton(icon('download')+' Exportar dados','export','','secondary'))+`<div class="metrics-grid">${metric('Consumo no cenário',num(kwh)+'<small> kWh</small>','Acumulado ilustrativo do turno')}${metric('Demanda atual',num(demand)+'<small> kW</small>','Referência de contrato: 220 kW')}${metric('Custo estimado',money(kwh*state.settings.energyRate),`${money(state.settings.energyRate)}/kWh · tarifa de exemplo`)}${metric('Uso da referência',num(demand/220*100,1)+'<small>%</small>',demand>220?'Acima da referência de exemplo':'Abaixo da referência de exemplo')}</div><div class="two-columns wide-left"><section class="panel">${panelHead('Perfil de demanda','Valores de exemplo ao longo do turno',`<span class="badge ${demand>220?'attention':'running'}"><i></i>${demand>220?'Verificar demanda':'Dentro da referência'}</span>`)}${chart(series,['10h','11h','12h','13h','14h','15h',clock(state)],'kW','energy','#8a7c3c')}<p class="panel-note">A referência de 220 kW é ilustrativa. A estimativa usa a tarifa configurada, sem encargos adicionais.</p></section><section class="panel">${panelHead('Distribuição da demanda','Exemplo por área de processo')}<div class="area-bars">${[['Preparação',68],['Envase',54],['Embalagem',38],['Utilidades',22]].map(([label,v])=>`<div><p>${label}<strong>${num(v*demand/182,1)} kW</strong></p><div class="progress"><span style="width:${v/182*100}%"></span></div></div>`).join('')}</div><a class="panel-link" href="#/configuracoes">Revisar tarifa de exemplo ↗</a></section></div>`;}
function stockView(){let list=state.stock.filter(i=>(i.name+' '+i.id+' '+i.category).toLowerCase().includes((queries[route]||'').toLowerCase()));if(filters[route]==='low')list=list.filter(i=>i.qty<i.min);const low=state.stock.filter(i=>i.qty<i.min);return heading('Estoque e materiais',subtitles[route],actionButton(icon('download')+' Exportar estoque','export'))+`<div class="metrics-grid three">${metric('Materiais cadastrados',state.stock.length,'Itens fictícios da unidade')}${metric('Abaixo do mínimo',low.length,'Pontos que merecem planejamento de reposição')}${metric('Materiais disponíveis',state.stock.length-low.length,'Quantidade igual ou superior ao mínimo')}</div><section class="panel">${panelHead('Disponibilidade de materiais','Registre uma entrada de exemplo e acompanhe os indicadores.')}<div class="table-toolbar">${searchField('Buscar material ou código')}<select class="select" data-filter aria-label="Disponibilidade do estoque"><option value="all">Todos os materiais</option><option value="low" ${filters[route]==='low'?'selected':''}>Abaixo do mínimo</option></select></div><div class="table-scroll"><table><thead><tr><th>Material</th><th>Categoria</th><th>Disponível</th><th>Mínimo</th><th>Local</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small class="cell-caption">${i.id}</small></td><td>${esc(i.category)}</td><td><strong class="${i.qty<i.min?'warning-text':''}">${num(i.qty)} ${i.unit}</strong></td><td>${num(i.min)} ${i.unit}</td><td>${i.location}</td><td>${actionButton('Registrar entrada','receive',i.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty-row">Nenhum material para este filtro.</td></tr>'}</tbody></table></div></section>`;}
function analyticsView(){const m=metrics(state),losses=[['Setup e troca',12.8],['Intervenção de manutenção',8],['Abastecimento de material',5],['Ajuste do processo',3]];return heading('Análises e eficiência',subtitles[route],actionButton(icon('download')+' Exportar análise','export'))+`<section class="oee-explanation"><div><p>Eficiência global do equipamento</p><strong>${num(m.oee,1)}<small>%</small></strong><span>Meta de exemplo: 90% · diferença de ${num(90-m.oee,1)} pontos</span></div><div class="oee-equation">${[['Disponibilidade',m.availability],['Performance',m.performance],['Qualidade',m.quality]].map(([label,v],i)=>`<article><span>${label}</span><strong>${num(v,1)}%</strong><div class="progress"><span style="width:${v}%"></span></div></article>${i<2?'<b aria-hidden="true">×</b>':''}`).join('')}</div></section><div class="two-columns"><section class="panel">${panelHead('Onde o tempo foi perdido','28,8 minutos de perdas em 480 minutos de referência')}<div class="area-bars">${losses.map(([label,v])=>`<div><p>${label}<strong>${num(v,1)} min</strong></p><div class="progress"><span style="width:${v/28.8*100}%"></span></div></div>`).join('')}</div></section><section class="panel">${panelHead('Leitura do indicador','Uma composição que ajuda a direcionar a investigação.')}<div class="insight-list"><article><span>01</span><div><h3>Disponibilidade</h3><p>Considera o tempo disponível em relação à janela de referência: 451,2 / 480 minutos.</p></div></article><article><span>02</span><div><h3>Performance</h3><p>Representa o ritmo em relação à condição de referência do exemplo.</p></div></article><article><span>03</span><div><h3>Qualidade</h3><p>Representa a proporção ilustrativa de unidades conformes.</p></div></article></div><p class="panel-note">A metodologia e as fontes de cada indicador precisam ser definidas no projeto real.</p></section></div>`;}
function reportsView(){return heading('Relatórios e exportação',subtitles[route])+`<section class="report-intro"><div>${icon('reports')}<h2>O contexto acompanha o dado.</h2><p>Gere um arquivo CSV com os registros atuais desta demonstração. Ordens, manutenção e estoque refletem as ações realizadas por você.</p></div><span>Arquivo com identificação<br>de dados demonstrativos</span></section><div class="report-grid">${[['overview','Resumo da operação','Indicadores, plano de produção e horário do cenário.','overview'],['ordens','Ordens de produção','Quantidades, andamento, prioridade e equipamento.','orders'],['manutencao','Manutenção','Solicitações, estados e progresso dos checklists.','maintenance'],['energia','Energia','Consumo, demanda e estimativa pela tarifa configurada.','energy'],['estoque','Inventário de materiais','Quantidades, mínimos e localizações dos itens.','stock'],['historico','Histórico de eventos','Ações e registros do cenário demonstrativo.','history']].map(([key,title,desc,ico])=>`<article class="report-card">${icon(ico)}<h2>${title}</h2><p>${desc}</p><button class="button secondary" data-action="report" data-id="${key}">${icon('download')} Baixar CSV</button></article>`).join('')}</div>`;}
function usersView(){return heading('Perfis de acesso',subtitles[route])+`<div class="context-note">${icon('users')}<p><strong>Perfis ilustrativos.</strong> Os nomes são fictícios. Esta demo não tem autenticação e não representa um controle de acesso real.</p></div><section class="panel">${panelHead('Pessoas e responsabilidades','Abra um perfil para conhecer um exemplo de permissões.')}<div class="table-scroll"><table><thead><tr><th>Pessoa fictícia</th><th>Perfil</th><th>Abrangência</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="person"><span>${u.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><strong>${esc(u.name)}</strong></div></td><td>${esc(u.role)}</td><td>${esc(u.area)}</td><td>${actionButton('Ver permissões','user',u.id)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function historyView(){const list=state.history.filter(e=>(e.module+' '+e.action+' '+e.detail).toLowerCase().includes((queries[route]||'').toLowerCase())&&(!filters[route]||filters[route]==='all'||e.module===filters[route]));return heading('Histórico de eventos',subtitles[route],actionButton(icon('download')+' Exportar histórico','export'))+`<section class="panel">${panelHead('Rastreabilidade do exemplo',`${state.history.length} registros disponíveis neste navegador`)}<div class="table-toolbar">${searchField('Buscar evento ou referência')}<select class="select" data-filter aria-label="Módulo do evento"><option value="all">Todos os módulos</option>${['Sistema','Produção','Manutenção','Alertas','Estoque'].map(m=>`<option ${filters[route]===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="table-scroll"><table><thead><tr><th>Horário do cenário</th><th>Módulo</th><th>Evento</th><th>Contexto</th></tr></thead><tbody>${list.map(ev=>`<tr><td class="tabular">${esc(ev.time)}</td><td><span class="neutral-tag">${esc(ev.module)}</span></td><td><strong>${esc(ev.action)}</strong></td><td>${esc(ev.detail)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-row">Nenhum evento para este filtro.</td></tr>'}</tbody></table></div></section>`;}
function settingsView(){return heading('Configurações do exemplo',subtitles[route])+`<div class="two-columns"><section class="panel settings-panel">${panelHead('Parâmetros demonstrativos','Os ajustes afetam somente este cenário local.')}<form id="settings-form"><label for="threshold">Limite de atenção do misturador (°C)</label><input id="threshold" name="threshold" type="number" min="20" max="120" step="1" required value="${state.settings.threshold}"><p class="field-help">O misturador do cenário com atenção está em 74 °C. O limite define a condição exibida nos módulos.</p><label for="energyRate">Tarifa de energia de exemplo (R$/kWh)</label><input id="energyRate" name="energyRate" type="number" min="0.01" max="10" step="0.01" required value="${state.settings.energyRate}"><p class="field-help">Usada apenas para a estimativa simplificada de custo no módulo Energia.</p><button class="button primary" type="submit">Salvar parâmetros do exemplo</button></form></section><section class="panel">${panelHead('Como funciona esta demonstração','Transparência sobre o ambiente.')}<div class="architecture-list"><div><span>Dados fictícios</span><p>Indicadores e cadastros foram preparados para demonstrar possibilidades.</p></div><div><span>Ações locais</span><p>Ordens, solicitações e entradas ficam apenas no armazenamento deste navegador.</p></div><div><span>Sem conexão industrial</span><p>Nenhuma ação controla máquina, CLP ou processo real.</p></div><div><span>Um ponto de partida</span><p>Integrações e módulos são definidos de acordo com cada projeto.</p></div></div><button class="button secondary" data-action="reset">Reiniciar o cenário</button></section></div>`;}
const views={'visao-geral':overview,equipamentos:equipment,supervisao:processView,ordens:ordersView,manutencao:maintenanceView,energia:energyView,estoque:stockView,analises:analyticsView,relatorios:reportsView,usuarios:usersView,historico:historyView,configuracoes:settingsView};
function render(){const active=document.activeElement;const preserve=active?.hasAttribute('data-query');const pos=active?.selectionStart;const title=modules.find(m=>m[0]===route)?.[1]||'Visão geral';$('#page-root').innerHTML=views[route]();$('#breadcrumb').textContent=title;document.title=title+' — RPC Suite | Demonstração';$('#maintenance-count').textContent=state.tasks.filter(t=>t.status!=='done').length;document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(preserve){const input=$('[data-query]');input?.focus({preventScroll:true});try{input?.setSelectionRange(pos,pos);}catch{}}}
function navigate(){const key=location.hash.replace(/^#\/?/,'');route=Object.hasOwn(views,key)?key:'visao-geral';$('#sidebar').classList.remove('open');$('#mobile-toggle').setAttribute('aria-expanded','false');$('#search-results').hidden=true;render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',navigate);
$('#mobile-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-toggle').setAttribute('aria-expanded',String(open));});
$('#close-sidebar').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobile-toggle').setAttribute('aria-expanded','false');$('#mobile-toggle').focus();});
document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#mobile-toggle')){$('#sidebar').classList.remove('open');$('#mobile-toggle').setAttribute('aria-expanded','false');}});
$('#profile-button').addEventListener('click',()=>{location.hash='/usuarios';});
function detail(kicker,title,body){if(!$('#detail-dialog').open)lastTrigger=document.activeElement;$('#detail-kicker').textContent=kicker;$('#detail-title').textContent=title;$('#detail-body').innerHTML=body;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;$('#close-detail').focus({preventScroll:true});}
function assetDetail(id){const a=currentAssets(state).find(x=>x.id===id);if(!a)return;const related=alarms(state).filter(x=>x.asset===id);const tasks=state.tasks.filter(t=>t.asset===id&&t.status!=='done');const vals=[.88,.91,.94,.92,.98,1].map(f=>Math.round(a.value*f*10)/10);detail(a.id+' · '+a.area,a.name,`<div class="detail-status">${badge(a.status)}<span>Cenário ${clock(state)}</span></div><div class="detail-value"><span>${a.variable}</span><strong>${num(a.value, a.value%1?1:0)} <small>${a.unit}</small></strong></div><section class="detail-section"><h3>Tendência de exemplo</h3>${chart(vals,['−25min','−20min','−15min','−10min','−5min','Agora'],a.unit,'detail')}</section>${related.length?`<section class="detail-section"><h3>Condições encontradas</h3>${related.map(al=>`<div class="detail-alert"><strong>${al.title}</strong><p>${esc(al.detail)}</p>${al.acknowledged?'<span class="ack-label">Ciência registrada; condição permanece.</span>':actionButton('Registrar ciência','ack',al.id)}</div>`).join('')}</section>`:''}<section class="detail-section"><h3>Manutenção relacionada</h3>${tasks.map(t=>`<button class="detail-reference" data-action="task" data-id="${t.id}"><span>${t.id}<strong>${esc(t.title)}</strong></span>↗</button>`).join('')||'<p>Nenhuma solicitação pendente para este equipamento.</p>'}${actionButton(icon('plus')+' Criar solicitação de exemplo','task-from-asset',id)}</section><p class="detail-disclaimer">Os valores são fictícios. Esta tela demonstra acompanhamento e não contém comandos para máquinas reais.</p>`);}
function orderDetail(id){const o=state.orders.find(x=>x.id===id);if(!o)return;detail('Ordem de produção',o.id,`<div class="detail-status">${badge(o.status,o.status==='running'?'Em produção':undefined)}<span>Prioridade ${o.priority}</span></div><h3 class="detail-product">${esc(o.product)}</h3><div class="detail-value"><span>Produzido / planejado</span><strong>${num(o.done)} <small>/ ${num(o.qty)} un</small></strong><div class="progress"><span style="width:${o.done/o.qty*100}%"></span></div></div><div class="detail-facts"><div><span>Equipamento</span><strong>Envasadora 01</strong></div><div><span>Atendimento da ordem</span><strong>${num(o.done/o.qty*100,1)}%</strong></div></div><p class="detail-disclaimer">Ao avançar o cenário, uma ordem em produção recebe até 120 unidades simuladas. Concluir o exemplo preenche a quantidade restante.</p><div class="detail-actions">${o.status==='planned'?actionButton('Iniciar ordem no exemplo','start-order',id,'primary'):o.status==='running'?actionButton('Concluir ordem no exemplo','finish-order',id,'primary'):''}${actionButton('Consultar equipamento','asset',o.asset)}</div>`);}
function taskDetail(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;detail('Solicitação de manutenção',t.id,`<div class="detail-status">${badge(t.status,t.status==='running'?'Em execução':undefined)}<span>Prioridade ${t.priority}</span></div><h3 class="detail-product">${esc(t.title)}</h3><p>${esc(assetName(t.asset))} · ${t.asset}</p><div class="detail-section"><h3>Contexto da solicitação</h3><p>${esc(t.notes)}</p></div><div class="detail-section"><h3>Checklist de exemplo <small id="task-progress">${t.checks.filter(Boolean).length}/3</small></h3><div class="task-checklist">${['Verificação inicial registrada','Intervenção de exemplo verificada','Teste e orientação registrados'].map((label,i)=>`<label><input type="checkbox" data-check="${t.id}" data-index="${i}" ${t.checks[i]?'checked':''} ${t.status==='done'?'disabled':''}><span>${label}</span></label>`).join('')}</div></div>${t.status!=='done'?`<button class="button primary full-width" data-action="finish-task" data-id="${t.id}" id="finish-task-button" ${t.checks.every(Boolean)?'':'disabled'}>Concluir manutenção no exemplo</button>`:'<div class="success-note">Checklist completo e encerramento registrado no histórico.</div>'}<p class="detail-disclaimer">Marcar o checklist e concluir esta solicitação altera apenas os registros fictícios da demonstração.</p>`);}
function userDetail(id){const u=state.users.find(x=>x.id===id);if(!u)return;const admin=u.role==='Gestão',maintenance=u.role==='Manutenção',operator=u.role==='Operação';detail('Pessoa fictícia · Perfil '+u.role,u.name,`<p>Um exemplo de organização de responsabilidades. Não existe autenticação ou aplicação de permissões nesta demo.</p><div class="permission-list">${[['Consultar indicadores',true],['Acompanhar equipamentos',true],['Registrar ordens de produção',admin||operator],['Registrar manutenção',admin||maintenance],['Consultar custos e gestão',admin],['Configurar acessos',admin]].map(([label,allowed])=>`<div><span>${label}</span><strong class="${allowed?'allowed':'muted'}">${allowed?'Permitido no exemplo':'Somente consulta / sem acesso'}</strong></div>`).join('')}</div><p class="detail-disclaimer">No projeto real, acessos, autenticação e políticas precisam ser implementados conforme os requisitos da empresa.</p>`);}
function stockDetail(id){const item=state.stock.find(i=>i.id===id);if(!item)return;detail(item.id+' · '+item.category,item.name,`<div class="detail-status">${badge(item.qty<item.min?'attention':'running',item.qty<item.min?'Abaixo do mínimo':'Disponível')}<span>Local ${esc(item.location)}</span></div><div class="detail-value"><span>Quantidade disponível</span><strong>${num(item.qty)} <small>${item.unit}</small></strong></div><div class="detail-facts"><div><span>Mínimo de exemplo</span><strong>${num(item.min)} ${item.unit}</strong></div><div><span>Categoria</span><strong>${esc(item.category)}</strong></div></div><div class="detail-actions">${actionButton('Registrar entrada de exemplo','receive',id,'primary')}</div><p class="detail-disclaimer">A entrada atualiza somente o estoque fictício e fica registrada no histórico deste navegador.</p>`);}
function form(title,kind,body,id=''){$('#form-title').textContent=title;$('#form-body').innerHTML=`<form data-demo-form="${kind}" data-id="${esc(id)}"><p class="form-demo-note">Use apenas dados fictícios. Este registro fica neste navegador.</p>${body}<p id="form-error" role="alert" hidden></p><div class="form-actions"><button type="button" class="button secondary" data-action="close-form">Cancelar</button><button type="submit" class="button primary">Registrar no exemplo</button></div></form>`;$('#form-dialog').showModal();}
function orderForm(){form('Nova ordem de produção','order','<label for="product">Produto / descrição</label><input id="product" name="product" maxlength="100" required placeholder="Ex.: Frasco 500 mL · Lote D"><div class="form-two"><div><label for="qty">Quantidade planejada</label><input id="qty" name="qty" type="number" min="1" max="1000000" step="1" value="600" required></div><div><label for="priority">Prioridade</label><select id="priority" name="priority"><option>Normal</option><option>Alta</option></select></div></div><label>Equipamento do cenário</label><p class="readonly-field">Envasadora 01 · FL-01</p>');}
function taskForm(asset=''){form('Nova solicitação de manutenção','task',`<label for="task-title">Serviço / verificação</label><input id="task-title" name="title" required maxlength="100" placeholder="Ex.: Verificar sensor de nível"><div class="form-two"><div><label for="task-asset">Equipamento</label><select id="task-asset" name="asset">${currentAssets(state).map(a=>`<option value="${a.id}" ${a.id===asset?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div><label for="task-priority">Prioridade</label><select id="task-priority" name="priority"><option>Normal</option><option>Alta</option></select></div></div><label for="task-notes">Contexto</label><textarea id="task-notes" name="notes" rows="3" maxlength="500" placeholder="Registre uma descrição fictícia da necessidade."></textarea>`);}
function stockForm(id){const i=state.stock.find(x=>x.id===id);if(!i)return;form('Entrada de material','receive',`<div class="form-material"><strong>${esc(i.name)}</strong><p>${i.id} · Disponível: ${num(i.qty)} ${i.unit}</p></div><label for="receive-qty">Quantidade de entrada (${i.unit})</label><input id="receive-qty" name="qty" type="number" min="1" max="100000" step="1" value="5" required>`,id);}
function exportCSV(kind){const csv=toCSV(reportRows(state,kind));const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='rpc-suite-demo-'+kind+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Relatório CSV gerado com dados demonstrativos.');}
function reset(){state=initialState();queries={};filters={};chartPeriod='turno';persist();if($('#detail-dialog').open)$('#detail-dialog').close();render();toast('Cenário reiniciado. Os registros fictícios foram restaurados.');}
$('#close-detail').addEventListener('click',()=>$('#detail-dialog').close());$('#close-form').addEventListener('click',()=>$('#form-dialog').close());$('#detail-dialog').addEventListener('close',()=>{if(lastTrigger?.isConnected)lastTrigger.focus({preventScroll:true});else $('#workspace').focus({preventScroll:true});});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{if(d.contains($('#toast')))document.body.append($('#toast'));}));
[$('#detail-dialog'),$('#form-dialog')].forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}));
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){
 case 'asset':assetDetail(id);break;case 'stock':stockDetail(id);break;case 'order':orderDetail(id);break;case 'task':taskDetail(id);break;case 'user':userDetail(id);break;
 case 'advance':mutate(()=>advance(state),'Cenário avançado. A produção e os registros foram atualizados.');break;
 case 'ack':if(mutate(()=>acknowledge(state,id),'Ciência registrada. A condição de processo continua disponível.')!==false&&$('#detail-dialog').open){const a=alarms(state).find(x=>x.id===id);if(a)assetDetail(a.asset);}break;
 case 'period':chartPeriod=id;render();break;case 'new-order':orderForm();break;case 'new-task':taskForm();break;case 'task-from-asset':taskForm(id);break;
 case 'receive':stockForm(id);break;
 case 'start-order':if(mutate(()=>startOrder(state,id),'Ordem iniciada no cenário.')!==false&&$('#detail-dialog').open)orderDetail(id);break;
 case 'finish-order':if(mutate(()=>finishOrder(state,id),'Ordem concluída no exemplo. Indicadores atualizados.')!==false&&$('#detail-dialog').open)orderDetail(id);break;
 case 'finish-task':if(mutate(()=>finishTask(state,id),'Manutenção concluída e registrada no histórico.')!==false)$('#detail-dialog').close();break;
 case 'export':exportCSV(route);break;case 'report':exportCSV(id);break;case 'reset':reset();break;case 'close-form':$('#form-dialog').close();break;
 }});
document.addEventListener('input',e=>{if(e.target.matches('[data-query]')){queries[route]=e.target.value;render();}});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-filter]')){filters[route]=e.target.value;render();}
 if(e.target.id==='scenario'){state.scenario=e.target.value;event(state,'Sistema','Cenário de processo alterado',state.scenario==='normal'?'Operação estável':'Com pontos de atenção');persist();render();}
 if(e.target.matches('[data-check]')){const t=state.tasks.find(t=>t.id===e.target.dataset.check);if(!t||t.status==='done')return;t.checks[Number(e.target.dataset.index)]=e.target.checked;persist();$('#task-progress').textContent=t.checks.filter(Boolean).length+'/3';$('#finish-task-button').disabled=!t.checks.every(Boolean);render();}
});
document.addEventListener('submit',e=>{
 if(e.target.id==='settings-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));mutate(()=>saveSettings(state,data),'Parâmetros atualizados no cenário de exemplo.');}
 if(e.target.matches('[data-demo-form]')){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const type=e.target.dataset.demoForm;let id;if(type==='order')id=createOrder(state,data);if(type==='task')id=createTask(state,data);if(type==='receive')receiveStock(state,e.target.dataset.id,data.qty);persist();render();$('#form-dialog').close();toast(type==='receive'?'Entrada de material registrada.':`${id} criado no exemplo.`);if(type==='task')taskDetail(id);if(type==='receive'&&$('#detail-dialog').open)stockDetail(e.target.dataset.id);}catch(err){$('#form-error').textContent=err.message;$('#form-error').hidden=false;}}
});
$('#reset-demo').addEventListener('click',reset);
function search(term){const q=term.trim().toLowerCase();const box=$('#search-results');if(q.length<2){box.hidden=true;return;}const results=[...currentAssets(state).map(a=>({title:a.name,meta:a.id+' · Equipamento',action:'asset',id:a.id})),...state.orders.map(o=>({title:o.product,meta:o.id+' · Ordem de produção',action:'order',id:o.id})),...state.tasks.map(t=>({title:t.title,meta:t.id+' · Manutenção',action:'task',id:t.id})),...state.stock.map(i=>({title:i.name,meta:i.id+' · Material',action:'stock',id:i.id}))].filter(item=>(item.title+' '+item.meta).toLowerCase().includes(q)).slice(0,8);box.innerHTML=`<p>Resultados da demonstração</p>${results.map(r=>`<button data-action="${r.action}" data-id="${r.id}"><strong>${esc(r.title)}</strong><span>${esc(r.meta)}</span></button>`).join('')||'<div class="search-empty">Nenhum registro encontrado. Tente “envase”, “OP-2402” ou “sensor”.</div>'}`;box.hidden=false;}
$('#global-search').addEventListener('input',e=>search(e.target.value));$('#search-results').addEventListener('click',e=>{if(e.target.closest('button'))$('#search-results').hidden=true;});
document.addEventListener('click',e=>{if(!e.target.closest('.global-search')&&!e.target.closest('#search-results'))$('#search-results').hidden=true;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#search-results').hidden=true;$('#sidebar').classList.remove('open');$('#mobile-toggle').setAttribute('aria-expanded','false');}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#global-search').focus();}});
const tourSteps=[
 {route:'visao-geral',title:'Comece pelo que importa.',text:'Veja a produção, os estados dos equipamentos e as condições que merecem atenção. Os números pertencem a um cenário fictício de envase.',icon:'overview'},
 {route:'supervisao',title:'Entre no processo.',text:'O sinótico liga o tanque, a mistura e o envase. Clique nos equipamentos para consultar variáveis, tendências e condições de exemplo.',icon:'process'},
 {route:'manutencao',title:'Da informação à ação.',text:'Uma ocorrência pode dar origem a uma solicitação. Abra uma manutenção, experimente o checklist e consulte o registro no histórico.',icon:'maintenance'},
 {route:'ordens',title:'Planejamento e execução juntos.',text:'Crie uma ordem fictícia. Ao avançar o cenário, a produção de uma ordem ativa evolui e os indicadores acompanham a mudança.',icon:'orders'},
 {route:'relatorios',title:'Leve a informação com você.',text:'Baixe um CSV dos registros demonstrativos. Uma solução real pode integrar as fontes, os módulos e os relatórios que a sua empresa precisa.',icon:'reports'}
];
function showTour(){const s=tourSteps[tourStep];if(location.hash!=='#/'+s.route)location.hash='/'+s.route;$('#tour-count').textContent=`${tourStep+1} de ${tourSteps.length}`;$('#tour-title').textContent=s.title;$('#tour-text').textContent=s.text;$('#tour-illustration').innerHTML=icon(s.icon);$('#tour-previous').disabled=tourStep===0;$('#tour-next').textContent=tourStep===tourSteps.length-1?'Começar a explorar':'Continuar';}
$('#tour-start').addEventListener('click',()=>{tourStep=0;showTour();$('#tour-dialog').showModal();});$('#tour-previous').addEventListener('click',()=>{tourStep=Math.max(0,tourStep-1);showTour();});$('#tour-next').addEventListener('click',()=>{if(tourStep===tourSteps.length-1)$('#tour-dialog').close();else{tourStep++;showTour();}});$('#close-tour').addEventListener('click',()=>$('#tour-dialog').close());
navigate();
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('#workspace').focus();$('#workspace').scrollIntoView({block:'start'});});
